import React, { useState } from 'react';

// Simplified button for the flow
const FlowButton = ({ label, emoji, isBlinking, onClick, isEasyMode }) => (
    <button 
        onClick={onClick}
        style={{
            padding: '20px 40px',
            margin: '10px',
            border: `3px solid ${isBlinking ? 'red' : 'lightgray'}`,
            backgroundColor: isBlinking ? 'yellow' : 'white',
            fontWeight: 'bold',
            fontSize: isEasyMode ? '30px' : '18px',
            animation: isBlinking ? 'blink 1s infinite' : 'none',
            cursor: 'pointer',
            transition: 'all 0.3s'
        }}
    >
        <span role="img" aria-label={label} style={{fontSize: isEasyMode ? '60px' : '30px'}}>{emoji}</span>
        <p>{label}</p>
    </button>
);

function AppointmentFlow({ isEasyMode, appointment, goToTransportStatus }) {
    // 0: Initial (Date Blinking), 1: Ask Transport, 2: Choose Needs, 3: Confirm/Done
    const [step, setStep] = useState(0); 
    const [needsTransport, setNeedsTransport] = useState(null); // true/false
    const [transportNeed, setTransportNeed] = useState(null); // 'wheelchair', 'bedridden', 'slow'

    // Simulate sending data to backend
    const sendTransportData = () => {
        const data = {
            appointmentDate: appointment.date,
            appointmentTime: appointment.time,
            needsTransport: needsTransport,
            transportNeed: transportNeed,
        };
        console.log('--- Data Sent (Mock JSON/Backend) ---', data);
        // In a real app: axios.post('/api/book-transport', data);
        setStep(3); // Go to final confirmation state
        setTimeout(goToTransportStatus, 2000); // Redirect after confirmation
    };

    // Style helper functions
    const getBlinkingStyle = (currentStep) => ({
        border: `5px solid ${step === currentStep ? 'lime' : 'lightgray'}`,
        backgroundColor: step === currentStep ? 'lightgreen' : '#eee',
        animation: step === currentStep ? 'blink 1.5s infinite' : 'none',
    });

    return (
        <div style={{ padding: '20px', textAlign: 'center' }}>
            <h2>Appointment Details</h2>
            
            {/* Blinking Date/Time Area */}
            <div 
                style={{
                    padding: '30px', 
                    marginBottom: '20px', 
                    borderRadius: '15px', 
                    ...getBlinkingStyle(0),
                    fontSize: isEasyMode ? '48px' : '24px',
                    fontWeight: 'bold'
                }}
                onClick={() => isEasyMode && console.log("Audio: 'Your appointment is on December 10th, at 10 AM.'")}
            >
                <p>{appointment.date}</p>
                <p>{appointment.time}</p>
            </div>

            {/* STEP 1: Do you need transport? */}
            <div style={getBlinkingStyle(1)} onClick={() => step === 1 && console.log("Audio: 'Do you need a ride?'")}>
                <p style={{fontSize: isEasyMode ? '36px' : '20px', fontWeight: 'bold'}}>
                    Do you need transportation?
                </p>
                <FlowButton
                    label="Yes"
                    emoji="✅"
                    isBlinking={step === 1}
                    isEasyMode={isEasyMode}
                    onClick={() => { setNeedsTransport(true); setStep(2); }}
                />
                <FlowButton
                    label="No"
                    emoji="❌"
                    isBlinking={step === 1}
                    isEasyMode={isEasyMode}
                    onClick={() => { setNeedsTransport(false); setStep(3); sendTransportData(); }}
                />
            </div>
            
            {/* STEP 2: Choose Needs */}
            {step >= 2 && needsTransport && (
                <div style={getBlinkingStyle(2)} onClick={() => step === 2 && console.log("Audio: 'Choose your transport needs.'")}>
                    <h3 style={{fontSize: isEasyMode ? '36px' : '20px'}}>
                        What kind of transportation do you need?
                    </h3>
                    <div style={{ display: 'flex', justifyContent: 'center' }}>
                        <FlowButton
                            label="Wheelchair"
                            emoji="♿"
                            isBlinking={step === 2 && transportNeed !== 'wheelchair'}
                            isEasyMode={isEasyMode}
                            onClick={() => setTransportNeed('wheelchair')}
                        />
                        <FlowButton
                            label="Bedridden"
                            emoji="🛏️"
                            isBlinking={step === 2 && transportNeed !== 'bedridden'}
                            isEasyMode={isEasyMode}
                            onClick={() => setTransportNeed('bedridden')}
                        />
                        <FlowButton
                            label="Slow Walking"
                            emoji="🚶"
                            isBlinking={step === 2 && transportNeed !== 'slow'}
                            isEasyMode={isEasyMode}
                            onClick={() => setTransportNeed('slow')}
                        />
                    </div>
                    
                    {transportNeed && (
                        <FlowButton
                            label="Confirm and Book"
                            emoji="👍"
                            isBlinking={step === 2}
                            isEasyMode={isEasyMode}
                            onClick={sendTransportData}
                        />
                    )}
                </div>
            )}
            
            {/* STEP 3: Final State */}
            {step === 3 && (
                <div style={{ marginTop: '20px', color: 'green', fontWeight: 'bold', fontSize: isEasyMode ? '48px' : '24px' }}>
                    {needsTransport ? '✅ Transport booked! Redirecting...' : '✅ Appointment confirmed.'}
                </div>
            )}
        </div>
    );
}

export default AppointmentFlow;
